{{ config(
            materialized='table',
                post_hook={
                    "sql": "WITH offline_no_jit AS ( SELECT CAST(BRANCH_CODE AS VARCHAR) AS BRANCH_CODE, MARKETPLACE_MAPPED, NEW_CATEGORY AS CATEGORY, COUNT(SKU_GROUP) AS SKU_COUNT_NO_JIT FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE NUM_SIZE_AVAILABLE > 3 GROUP BY CAST(BRANCH_CODE AS VARCHAR), MARKETPLACE_MAPPED, NEW_CATEGORY ), offline_jit AS ( SELECT CAST(BRANCH_CODE AS VARCHAR) AS BRANCH_CODE, MARKETPLACE_MAPPED, NEW_CATEGORY AS CATEGORY, COUNT(SKU_GROUP) AS SKU_COUNT_WITH_JIT FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE ( (CASE WHEN (XS_UNITS + JIT_XS_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (S_UNITS + JIT_S_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (M_UNITS + JIT_M_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (L_UNITS + JIT_L_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (XL_UNITS + JIT_XL_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (XXL_UNITS + JIT_2XL_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (XL3_UNITS + JIT_3XL_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (XL4_UNITS + JIT_4XL_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (XL5_UNITS + JIT_5XL_UNITS) > 0 THEN 1 ELSE 0 END) + (CASE WHEN (XL6_UNITS + JIT_6XL_UNITS) > 0 THEN 1 ELSE 0 END) ) >= 4 GROUP BY CAST(BRANCH_CODE AS VARCHAR), MARKETPLACE_MAPPED, NEW_CATEGORY ), category_delta AS ( SELECT scd.BRANCH_CODE, scd.CATEGORY, ROUND(scd.CATEGORY_BASE_STOCK / CAST(mf.\"DOI BOH\" AS FLOAT)) AS Ideal_SKU_COUNT FROM SNITCH_DB.MAPLEMONK.STORE_CATEGORY_DELTA scd LEFT JOIN SNITCH_DB.MAPLEMONK.MASTER_FILE mf ON scd.BRANCH_CODE = mf.\"STORE CODE\" ) SELECT n.BRANCH_CODE, n.MARKETPLACE_MAPPED, n.CATEGORY, n.SKU_COUNT_NO_JIT AS \"SKU COUNT WITHOUT JIT\", COALESCE(j.SKU_COUNT_WITH_JIT, 0) AS \"SKU COUNT WITH JIT\", d.Ideal_SKU_COUNT FROM offline_no_jit n LEFT JOIN offline_jit j ON n.BRANCH_CODE = j.BRANCH_CODE AND n.CATEGORY = j.CATEGORY LEFT JOIN category_delta d ON n.BRANCH_CODE = d.BRANCH_CODE AND n.CATEGORY = d.CATEGORY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            